namespace RockPro.CAD {
internal static class Rpc {
 internal static Dictionary<string,object> Obj(object v) { return v as Dictionary<string,object> ?? new Dictionary<string,object>(); }
 internal static string Str(Dictionary<string,object> d,string k) { return d.ContainsKey(k) && d[k]!=null ? Convert.ToString(d[k],CultureInfo.InvariantCulture):""; }
 internal static object[] Rows(object v) { var a=v as object[]; if(a!=null)return a; var l=v as ArrayList;return l==null?new object[0]:l.ToArray(); }
 internal static Dictionary<string,object> Call(string tool,object args) {
  var j=new JavaScriptSerializer();j.MaxJsonLength=16000000;
  var psi=new ProcessStartInfo(Path.GetFullPath(Path.Combine(Addin.Root,"..",".venv","Scripts","python.exe")),"\""+Path.Combine(Addin.Root,"mcp","server.py")+"\"");
  psi.UseShellExecute=false;psi.CreateNoWindow=true;psi.RedirectStandardInput=true;psi.RedirectStandardOutput=true;psi.RedirectStandardError=true;
  psi.StandardOutputEncoding=Encoding.UTF8;psi.StandardErrorEncoding=Encoding.UTF8;psi.EnvironmentVariables["PYTHONUTF8"]="1";
  using(var p=Process.Start(psi)) {
   var errors=p.StandardError.ReadToEndAsync();var input=new StreamWriter(p.StandardInput.BaseStream,new UTF8Encoding(false));input.AutoFlush=true;
   input.WriteLine(j.Serialize(new {jsonrpc="2.0",id=1,method="initialize",@params=new {protocolVersion="2025-06-18",capabilities=new {},clientInfo=new {name="rockpro-desktop",version="0.2"}}}));input.Flush();
   Read(p);
   input.WriteLine(j.Serialize(new {jsonrpc="2.0",method="notifications/initialized"}));
   input.WriteLine(j.Serialize(new {jsonrpc="2.0",id=2,method="tools/call",@params=new {name=tool,arguments=args}}));input.Flush();
   var reply=Rpc.Obj(j.DeserializeObject(Read(p)));input.Close();
   if(!p.WaitForExit(5000))p.Kill();
   if(reply.ContainsKey("error"))throw new Exception(j.Serialize(reply["error"]));
   var r=Obj(reply["result"]);var items=Rows(r["content"]);string text=Str(Obj(items[0]),"text");
   if(r.ContainsKey("isError") && Convert.ToBoolean(r["isError"]))throw new Exception(text);
   return Obj(j.DeserializeObject(text));
  }
 }
 static string Read(Process p) {var t=p.StandardOutput.ReadLineAsync();if(!t.Wait(180000)){try{p.Kill();}catch{}throw new TimeoutException(UiText.T("MCP przekroczyło 180 s. Sprawdź IronCAD i historię operacji przed ponowną próbą.","MCP did not respond within 180 seconds. Check IronCAD and operation history before retrying."));}if(t.Result==null)throw new Exception(UiText.T("MCP zamknęło połączenie bez odpowiedzi.","MCP closed the connection without a response."));return t.Result;}
}
// Shared conflict presentation: never changes a revision token unless the user explicitly reloads.
[ComVisible(false)]
internal static class RevisionUi {
 internal static Dictionary<string,object> Clone(Dictionary<string,object> value){var j=new JavaScriptSerializer();j.MaxJsonLength=16000000;return Rpc.Obj(j.DeserializeObject(j.Serialize(value)));}
 internal static Dictionary<string,object> Conflict(Exception error,string code){try{var d=Rpc.Obj(new JavaScriptSerializer().DeserializeObject(error.Message));return Rpc.Str(d,"code")==code&&d.ContainsKey("current")?d:null;}catch{return null;}}
 internal static string SystemValue(string value){switch(value){case "prototype":return UiText.T("Prototyp: bryły zastępcze, bez odbioru produkcyjnego","Prototype: proxy solids, not approved for production");case "project":return UiText.T("Karta projektu","Project card");case "stage":return UiText.T("Etap","Stage");case "inquiry":return UiText.T("Zapytanie","Inquiry");case "devices":return UiText.T("Urządzenia","Devices");case "layout":return UiText.T("Układ","Layout");case "geometry":return UiText.T("Konstrukcja","Structure");case "hardware":return UiText.T("Okucia","Hardware");case "wheels":return UiText.T("Koła","Wheels");case "documentation":return UiText.T("Dokumentacja","Documentation");case "materials":return UiText.T("Materiały","Materials");case "production":return UiText.T("Produkcja","Production");case "draft":return UiText.T("Roboczy","Draft");case "waiting":return UiText.T("Czeka na dane","Waiting for data");case "review":return UiText.T("Do sprawdzenia","Needs review");case "approved":return UiText.T("Zatwierdzony ręcznie","Manually approved");case "outdated":return UiText.T("Nieaktualny","Outdated");case "save_project":return UiText.T("Zapis karty projektu","Project card saved");case "manual_stage":return UiText.T("Ręczna zmiana statusu","Manual status change");case "cad_source_advanced":return UiText.T("Nowa kopia robocza CAD","New CAD working copy");case "project_inputs_changed":return UiText.T("Zmiana danych projektu","Project inputs changed");case "layout_saved":return UiText.T("Zapis układu","Layout saved");case "layout_changed":return UiText.T("Zmiana układu","Layout changed");default:return value;}}
 static string Value(Dictionary<string,object> d,string key){if(!d.ContainsKey(key)||d[key]==null)return "—";if(d[key] is Dictionary<string,object> || d[key] is object[])return new JavaScriptSerializer().Serialize(d[key]);return key=="status"?SystemValue(Rpc.Str(d,key)):Rpc.Str(d,key);}
 internal static string Caption(string key){switch(key){case "name":return UiText.T("Nazwa projektu","Project name");case "client":return UiText.T("Klient","Client");case "device":return UiText.T("Urządzenie","Device");case "quantity":return UiText.T("Liczba skrzyń","Number of cases");case "notes":return UiText.T("Notatki","Notes");case "source":return UiText.T("Plik ICS","ICS file");case "status":return UiText.T("Status etapu","Stage status");case "note":return UiText.T("Notatka etapu","Stage note");case "revision":return UiText.T("Wersja","Version");case "id":return "ID";case "created_at":return UiText.T("Data zapisu (UTC)","Saved at (UTC)");case "label":return UiText.T("Nazwa kopii","Copy name");case "validation":return UiText.T("Kontrola CAD","CAD check");case "integrity":return UiText.T("Integralność pliku","File integrity");case "path":return UiText.T("Plik archiwum","Archive file");case "report_path":return UiText.T("Plik raportu","Report file");case "sha256":return UiText.T("Suma kontrolna SHA256","SHA256 checksum");default:return key;}}
 internal static DataGridView DifferenceGrid(Dictionary<string,object> initial,Dictionary<string,object> mine,Dictionary<string,object> current){
  var grid=NewGrid();foreach(string name in new[]{UiText.T("Pole","Field"),UiText.T("Przy otwarciu","When opened"),UiText.T("Twoje zmiany","Your changes"),UiText.T("Aktualnie w bazie","Currently saved")})grid.Columns.Add(name,name);
  string[] keys=mine.ContainsKey("status")?new[]{"status","note","revision"}:new[]{"name","client","device","quantity","notes","source","revision"};
  foreach(string key in keys){string a=Value(initial,key),b=mine.ContainsKey(key)?Value(mine,key):a,c=Value(current,key);int n=grid.Rows.Add(Caption(key),a,b,c);if(a!=c)grid.Rows[n].Cells[3].Style.BackColor=Color.FromArgb(255,235,212);if(a!=b)grid.Rows[n].Cells[2].Style.BackColor=Color.FromArgb(226,241,250);}
  return grid;
 }
 static DataGridView NewGrid(){var g=new DataGridView {Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",10),SelectionMode=DataGridViewSelectionMode.CellSelect,MultiSelect=true};g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.DefaultCellStyle.Padding=new Padding(8);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(219,232,244);g.DefaultCellStyle.SelectionForeColor=Color.FromArgb(31,42,55);g.EnableHeadersVisualStyles=false;g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(230,236,242);g.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",10,FontStyle.Bold);g.ClipboardCopyMode=DataGridViewClipboardCopyMode.EnableAlwaysIncludeHeaderText;g.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize;g.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;g.ColumnHeadersDefaultCellStyle.Padding=new Padding(8,10,8,10);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.FromArgb(31,42,55);return g;}
 internal static bool ShowConflict(IWin32Window owner,string title,Dictionary<string,object> initial,Dictionary<string,object> mine,Dictionary<string,object> conflict){
  using(var f=new Form {Text=UiText.T("RockPro CAD — Konflikt zapisu | ","RockPro CAD — Save conflict | ")+title,Size=new Size(1100,620),MinimumSize=new Size(850,480),StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10),BackColor=Color.FromArgb(238,242,246),Padding=new Padding(18),AutoScaleMode=AutoScaleMode.Dpi}){
   var note=new Label {Dock=DockStyle.Top,Height=100,Text=UiText.T("Nie zapisano zmian: dane zostały zmienione od otwarcia formularza (v","Not saved: these data changed since you opened them (v")+Rpc.Str(conflict,"expected_revision")+" → v"+Rpc.Str(conflict,"current_revision")+UiText.T(").\nPorównaj wartości. Zamknięcie zachowa formularz i jego starą wersję. Wczytanie aktualnych danych odrzuci Twoje wpisy — możesz wcześniej skopiować komórki tabeli (Ctrl+C).",").\nCompare the values. Closing this window keeps your unsaved entries and original version. Reloading discards your entries. You can copy table cells first (Ctrl+C)."),Padding=new Padding(4,8,4,8)};
   var actions=new FlowLayoutPanel {Dock=DockStyle.Bottom,Height=62,FlowDirection=FlowDirection.RightToLeft};
   var keep=new StudioButton {Text=UiText.T("Wróć bez zapisywania","Return without saving"),Width=230,Height=44,BackColor=Color.White,DialogResult=DialogResult.Cancel};
   var reload=new StudioButton {Text=UiText.T("Wczytaj aktualne dane…","Reload saved data…"),Width=250,Height=44,BackColor=Color.FromArgb(237,102,21),ForeColor=Color.White};
   reload.Click+=delegate{if(MessageBox.Show(f,UiText.T("Odrzucić moje niezapisane wpisy i wczytać dane z kolumny Aktualnie w bazie?","Discard my unsaved entries and load the values in Currently saved?"),UiText.T("Wczytanie aktualnej wersji","Reload current version"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){f.DialogResult=DialogResult.Yes;f.Close();}};
   actions.Controls.Add(keep);actions.Controls.Add(reload);f.Controls.Add(DifferenceGrid(initial,mine,Rpc.Obj(conflict["current"])));f.Controls.Add(note);f.Controls.Add(actions);f.CancelButton=keep;f.AcceptButton=keep;bool shouldReload=f.ShowDialog(owner)==DialogResult.Yes;System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());return shouldReload;
  }
 }
 internal static void ShowHistory(IWin32Window owner,object[] events,bool more){using(var f=new Form {Text=UiText.T("RockPro CAD — Historia zmian karty i etapów","RockPro CAD — Project and stage history"),Size=new Size(1150,650),MinimumSize=new Size(850,480),StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10),Padding=new Padding(18),AutoScaleMode=AutoScaleMode.Dpi}){
  var grid=NewGrid();foreach(string col in new[]{UiText.T("Data lokalna","Local time"),UiText.T("Obszar","Area"),UiText.T("Autor / kanał","Author / channel"),UiText.T("Wersja","Version"),UiText.T("Powód","Reason")})grid.Columns.Add(col,col);
  foreach(object item in events){var e=Rpc.Obj(item);var p=Rpc.Obj(e.ContainsKey("payload")?e["payload"]:null);var before=Rpc.Obj(p.ContainsKey("before")?p["before"]:null);var after=Rpc.Obj(p.ContainsKey("after")?p["after"]:null);DateTimeOffset stamp;string date=DateTimeOffset.TryParse(Rpc.Str(e,"created_at"),out stamp)?stamp.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss"):Rpc.Str(e,"created_at");int n=grid.Rows.Add(date,SystemValue(Rpc.Str(p,"entity"))+" / "+SystemValue(Rpc.Str(p,"entity_key")),Rpc.Str(p,"actor")+" / "+Rpc.Str(p,"source"),Rpc.Str(before,"revision")+" → "+Rpc.Str(after,"revision"),SystemValue(Rpc.Str(p,"reason")));grid.Rows[n].Tag=p;}
  grid.CellDoubleClick+=delegate(object sender,DataGridViewCellEventArgs e){if(e.RowIndex<0)return;var p=Rpc.Obj(grid.Rows[e.RowIndex].Tag);using(var detail=new Form {Text=UiText.T("RockPro CAD — Zmiana: przed i po","RockPro CAD — Before and after"),Size=new Size(1050,550),StartPosition=FormStartPosition.CenterParent,Font=f.Font,Padding=new Padding(14)}){var before=Rpc.Obj(p.ContainsKey("before")?p["before"]:null);var after=Rpc.Obj(p.ContainsKey("after")?p["after"]:null);var diff=DifferenceGrid(before,after,after);diff.Columns[1].HeaderText=UiText.T("Przed","Before");diff.Columns[2].HeaderText=UiText.T("Po","After");diff.Columns[3].Visible=false;detail.Controls.Add(diff);detail.Controls.Add(new Label {Dock=DockStyle.Top,Height=60,Text=UiText.T("Porównanie zapisanej zmiany. Ta tabela jest tylko do odczytu. Zaznacz komórki i użyj Ctrl+C, aby je skopiować.","Read-only comparison of a saved change. Select cells and press Ctrl+C to copy them."),Padding=new Padding(8)});detail.ShowDialog(f);}};
  var note=new Label {Dock=DockStyle.Top,Height=74,Text=UiText.T("Kliknij dwukrotnie wiersz, aby porównać wartości przed i po. Autor i kanał są podawane przez program zapisujący zmianę; nie potwierdzają tożsamości osoby.\n","Double-click a row to compare before and after. Author/channel are reported by the calling app; they do not verify a person's identity.\n")+(more?UiText.T("Pokazano najnowsze 200 wpisów. Starsze wpisy dostępne przez get_history / before_id.","Showing the latest 200 entries. Older entries are available through the get_history API (before_id)."):events.Length+UiText.T(" wpisów. Starsze zdarzenia mogą nie zawierać pełnego porównania."," entries. Older events may not include a complete comparison.")),Padding=new Padding(4,10,4,8)};f.Controls.Add(grid);f.Controls.Add(note);f.ShowDialog(owner);
 }}
}
// Rounded, keyboard-accessible native button; no browser or extra UI runtime.
[ComVisible(false)]
internal sealed class StudioButton : Button {
 bool hover;
 public StudioButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;}
 protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}
 protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
 protected override void OnPaint(PaintEventArgs e){
  e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;
  e.Graphics.Clear(Parent==null?SystemColors.Control:Parent.BackColor);
  var r=new Rectangle(1,1,Width-3,Height-3);int d=16;
  using(var path=new GraphicsPath()){
   path.AddArc(r.Left,r.Top,d,d,180,90);path.AddArc(r.Right-d,r.Top,d,d,270,90);path.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);path.AddArc(r.Left,r.Bottom-d,d,d,90,90);path.CloseFigure();
   var fill=!Enabled?Color.FromArgb(225,229,235):hover?FlatAppearance.MouseOverBackColor:BackColor;
   using(var brush=new SolidBrush(fill))e.Graphics.FillPath(brush,path);
   using(var pen=new Pen(Focused?Color.FromArgb(237,102,21):FlatAppearance.BorderColor,Focused?2:1))e.Graphics.DrawPath(pen,path);
  }
  var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine;
  flags|=TextAlign==ContentAlignment.MiddleLeft?TextFormatFlags.Left:TextFormatFlags.HorizontalCenter;
  TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(14,0,Width-28,Height),Enabled?ForeColor:Color.Gray,flags);
 }
}
